return {
  drain: {
    hook: "entityActionPause", actionType: ["interrupt", "prowl", "turnAround"],
    stage: "beforeResolve", group: "book.t1.leash",
    active: (H, actor) => H.zone.isClose(H.zone.of(actor)),
    async run(H, actor, ctx) {
      await H.resource.adjustEntity(ctx.entityActor, { resolve: -1 });
      await H.chat.post(ctx.entityActor.name + " suffers 1 Resolve (Leash).", actor);
    },
  },
};
